  Vu = `سيتواصل معك فريق Steam عبر تذكرة دعم Steamworks إذا كانت هناك أي تغييرات مطلوبة على صفحتك. يمكنك عرض تذكرة دعم Steamworks وإضافة التعليقات إذا لزم الأمر بالنقر فوق الزر الموجود على اليمين.`,
  Hu = `وضع علامة تمت الموافقة سيسمح للشريك بنشر التخفيضات وإتاحتها`,
  Uu = `طلب التقييم...`,
  Wu = `طلب التقييم`,
  Gu = `ينشئ تذكرة لطلب تقييم للموافقة على نشر صفحة العروض. قم بذلك عندما تحتوي صفحة العروض الخاصة بك على الأعمال الفنية النهائية وتتضمن جميع الألعاب التي تريد عرضها.`,
  Ku = `سيؤدي ذلك إلى إنشاء تذكرة دعم Steamworks تطلب تقييم صفحة العروض الخاصة بك بواسطة Valve. يجب أن يتم ذلك فقط بمجرد الانتهاء من العناصر الفنية والرسائل الخاصة بك وقائمة الألعاب.`,
  qu = `يرجى التأكد من وصف عنوان الحدث والغرض منه بوضوح بالقرب من أعلى الصفحة. بالنسبة إلى العناصر المميزة المعروضة، قد تحتاج إلى نص في الجزء العلوي من صفحتك لوصف العناصر المميزة المعروضة الخاصة بك وكيفية عملها.`,
  Ju = `لا يمكن تعديل صفحة التخفيضات بعد تقييمها. إذا كنت بحاجة إلى إجراء تغييرات بعد التقييم أو بعد بدء الحدث، فيرجى كتابة تعليق يوضح هذه التغييرات وسبب عدم إكمالها قبل التقييم.`,
  Yu = `اختياري: المعلومات التي ترغب في إضافتها إلى المراجعين`,
  Xu = `اختر الشركاء الذين يمكن لأعضائهم أيضًا الوصول إلى تذكرة الطلب`,
  Zu = `اختياري: في حالة الاختيار، يمكن للأعضاء الآخرين من الشركاء الوصول إلى التذكرة والرد عليها. افتراضيًا، يمكنك فقط قراءة التذكرة التي تم إنشاؤها وتحديثها والرد عليها`,
  Qu = `تعذر إنشاء التذكرة، يرجى المحاولة لاحقًا`,
  $u = `لا يمكن إنشاء تذكرة جديدة؛ تذكرة من هذا النوع موجودة بالفعل. يرجى إكمال تقييم صفحة التخفيضات الأخرى قبل إرسال هذه الصفحة أو تحديث التذكرة الحالية لإضافة تقييم هذه الصفحة أيضًا.`,
  ed = `تم إنشاء التذكرة بنجاح!`,
  td = `عرض تذكرة التقييم...`,
  nd = `تمت الموافقة على صفحتك وهي جاهزة للنشر`,
  rd = `انتقل إلى علامة التبويب \\'نشر\\' لتنفيذ عملية النشر.`,
