  _V = `انقر هنا لترشيح %1$s لفئة على صفحة جوائز Steam.`,
  vV = `تم إغلاق الترشيحات. صوّت خلال التخفيضات الشتوية. سيتم الإعلان عن الفائزين في 2 يناير.`,
