  DV = `جائزة أكثر متعة مع الأصدقاء`,
  OV = `أسلوب بصري متميز`,
  kV = `أسلوب اللعب الأكثر ابتكارًا`,
  AV = `أفضل لعبة تكون سيئًا بها`,
  jV = `أفضل موسيقى تصويرية`,
  MV = `لعبة رائعة بقصة ثرية`,
  NV = `اجلس واسترخ`,
  PV = `لا تقترح فئة محددة، وبدلًا من ذلك دع معجبيك يختارون الفئة التي يعتقدون أنها الأنسب للعبة الخاصة بك. سيتضمن الحدث رابطًا يُوصّلك إلى صفحة الترشيحات.`,
  FV = `دون فئة`,
  IV = `ربما كان أسلوب لعبها الغامر أو قصتها المثيرة... شخصياتها المصممة جيدًا أو التصميم الأنيق أو اللعب الجماعي الذي لا يقاوم. مهما كان السبب، فإن الفائزة بجائزة أفضل لعبة لعام 2020 هي تحفة كلاسيكية.`,
  LV = `لعبة الـVR لهذا العام لا تكتفي بمحاكاة الواقع العادي، بل تتفوّق عليه. إنها تستغل إمكانيات الـVR بالكامل، وتدفع حدود العالم الافتراضي إلى آفاق جديدة.`,
  RV = `لقد صدرت هذه اللعبة منذ فترة. فريق التطوير تجاوز منذ زمن مرحلة إطلاق هذا المشروع الإبداعي، لكنهم ما زالوا يعتنون بلعبتهم ويواصلون دعمها. وحتى اليوم، وبعد كل هذه السنوات، لا تزال هذه اللعبة تحصل على محتوى جديد.`,
  zV = `هناك بعض الألعاب التي لا تكتمل متعتها عند اللعب بمفردك. ربما تحتاج إلى صديق يحمي ظهرك… أو ربما إلى صديق تطعَنُه في ظهره! في كلتا الحالتين، المتعة بانتظار من يجمع أصدقاءه ويخوض هذه اللعبة معهم.`,
  BV = `لا يطمح الأسلوب البصري إلى تحقيق الدقة الرسومية الواقعية (على الرغم من أن ذلك هدف جيد في حد ذاته)… إنه يصف مظهرًا وشعورًا مميزين يغمران اللعبة بأكملها.`,
  VV = `مصممو هذه اللعبة في طليعة التجارب الإبداعية، يقدمون منظورًا جديدًا ومفاجآت مثيرة. لقد أبهرت وألهمت وأمتعت هذه اللعبة بحداثة لم تُلعب من قبل.`,
  HV = `هذه هي اللعبة التي تكافئ الإصرار، وليست للجبناء. إنها أصعب لعبة أحببناها على الإطلاق.`,
  UV = `هذا البطل المجهول يستحق الشهرة بسبب موسيقاه المذهلة. إنها الموسيقى التصويرية الأصلية الأكثر نجاحًا! `,
  WV = `في بعض الأيام، لا يرضي شغفنا إلا لعبة تركز على السرد القصصي، وهذه اللعبة تفي بالغرض بقوة. إنها مشوّقة كأكثر المسلسلات درامية، ومتقنة كأروع سيناريوهات المسلسلات التلفزيونية المرموقة. تهانينا! على لعبة جعلتنا نشعر بكل ذلك!`,
  GV = `هذه اللعبة هي الملاذ ليوم حافل. إنها سلسة ومريحة وتسمح لهمومك بالاندثار. هذه اللعبة هي لحظتك للتمتع بالسلام الداخلي.`,
  KV = `هل تريد تغيير ترشيحك؟`,
  qV = `يمكنك ترشيح لعبة واحدة فقط لكل فئة، وقد قمت بالفعل بترشيح %1$s لهذه الفئة. هل ترغب بترشيح %2$s بدلًا منها؟`,
  JV = `صوّت`,
  YV = `تم التصويت`,
  XV = `تم إرسال التصويت`,
  ZV = `هل تريد تغيير تصويتك؟`,
  QV = `يمكنك التصويت للعبة واحدة فقط لكل فئة، وقد قمت بالفعل بالتصويت لـ%1$s لهذه الفئة. هل ترغب في تغيير تصويتك إلى %2$s؟`,
  $V = `يبدو أن حسابك مقيد. لمنع إساءة استخدام الترشيحات، يجب إنفاق 5 دولارات أمريكية على Steam من أجل المشاركة في جوائز Steam. %1$s لمزيد من المعلومات.`,
  eH = `يبدو أن حسابك مقيد. لمنع إساءة استخدام التصويت، يجب إنفاق 5 دولارات أمريكية على Steam من أجل المشاركة في جوائز Steam. %1$s لمزيد من المعلومات.`,
