  uH = `اجلس واسترخ`,
  dH = `ربما كان أسلوب لعبها الغامر أو قصتها المثيرة... شخصياتها المصممة جيدًا أو التصميم الأنيق أو اللعب الجماعي الذي لا يقاوم. مهما كان السبب، فإن الفائزة بجائزة لعبة العام هي تحفة كلاسيكية.`,
  fH = `لعبة الـVR لهذا العام لا تكتفي بمحاكاة الواقع العادي، بل تتفوّق عليه. إنها تستغل إمكانيات الـVR بالكامل، وتدفع حدود العالم الافتراضي إلى آفاق جديدة.`,
  pH = `لقد صدرت هذه اللعبة منذ فترة. فريق التطوير تجاوز منذ زمن مرحلة إطلاق هذا المشروع الإبداعي، لكنهم ما زالوا يعتنون بلعبتهم ويواصلون دعمها. وحتى اليوم، وبعد كل هذه السنوات، لا تزال هذه اللعبة تحصل على محتوى جديد.`,
  mH = `هناك بعض الألعاب التي لا تكتمل متعتها عند اللعب بمفردك. ربما تحتاج إلى صديق يحمي ظهرك… أو ربما إلى صديق تطعَنُه في ظهره! في كلتا الحالتين، المتعة بانتظار من يجمع أصدقاءه ويخوض هذه اللعبة معهم.`,
