  MH = `ربما كان أسلوب لعبها الغامر أو قصتها المثيرة... شخصياتها المصممة جيدًا أو التصميم الأنيق أو اللعب الجماعي الذي لا يقاوم. مهما كان السبب، فإن الفائزة بجائزة لعبة العام هي تحفة كلاسيكية.`,
