  PH = `لقد صدرت هذه اللعبة منذ فترة. فريق التطوير تجاوز منذ زمن مرحلة إطلاق هذا المشروع الإبداعي، لكنهم ما زالوا يعتنون بلعبتهم ويواصلون دعمها. وحتى اليوم، وبعد كل هذه السنوات، لا تزال هذه اللعبة تحصل على محتوى جديد.`,
  FH = `هناك بعض الألعاب التي لا تكتمل متعتها عند اللعب بمفردك. ربما تحتاج إلى صديق يحمي ظهرك… أو ربما إلى صديق تطعَنُه في ظهره! في كلتا الحالتين، المتعة بانتظار من يجمع أصدقاءه ويخوض هذه اللعبة معهم.`,
  IH = `لا يطمح الأسلوب البصري لتحقيق الدقة الرسومية الواقعية (على الرغم من أن ذلك هدف جيد في حد ذاته)… إنه يصف مظهرًا وشعورًا مميزين يغمران اللعبة بأكملها.`,
  LH = `مصممو هذه اللعبة في طليعة التجارب الإبداعية، يقدمون منظورًا جديدًا ومفاجآت مثيرة. لقد أبهرت وألهمت وأمتعت هذه اللعبة بحداثة لم تُلعب من قبل.`,
  RH = `هذه هي اللعبة التي تكافئ الإصرار، وليست للجبناء. إنها أصعب لعبة أحببناها على الإطلاق.`,
  zH = `هذا البطل المجهول يستحق الشهرة بسبب موسيقاه المذهلة. إنها الموسيقى التصويرية الأصلية الأكثر نجاحًا! `,
  BH = `في بعض الأيام، لا يرضي شغفنا إلا لعبة تركز على السرد القصصي، وهذه اللعبة تفي بالغرض بقوة. إنها مشوّقة كأكثر المسلسلات درامية، ومتقنة كأروع سيناريوهات المسلسلات التلفزيونية المرموقة. تهانينا! على لعبة جعلتنا نشعر بكل ذلك!`,
  VH = `هذه اللعبة هي الملاذ ليوم حافل. إنها سلسة ومريحة وتسمح لهمومك بالاندثار. هذه اللعبة هي لحظتك للتمتع بالسلام الداخلي.`,
  HH = `كانت هذه اللعبة جيدة جدًا، وأردت أخذها إلى كل مكان. وقد فعلت! ولحسن الحظ، فإن كل ما جعلها قابلة للعب على مكتبك أصبح أفضل في أثناء التنقل.`,
  UH = `VR فقط`,
  WH = `مدعومة بالـVR`,
  GH = `بقي %1$s حتى السحب العشوائي التالي!`,
  KH = `الوقت المتبقي حتى السحب العشوائي التالي.`,
  qH = `استمر في المشاهدة لفرصة للفوز!`,
  JH = `السحب العشوائي جارٍ`,
  YH = `هناك عدد من الفائزين المحظوظين حتى الآن!`,
  XH = `انتهت المسابقة الآن، شكرًا لمشاركتكم.`,
  ZH = `لقد انتهى السحب الآن مع %1$s من الفائزين المحظوظين، شكرًا لمشاركتك.`,
  QH = `انقر لمعرفة المزيد عن الجوائز والفائزين والقواعد`,
  $H = `تحقق كل يوم للحصول على هدية جديدة من الإمبراطور!`,
