  gU = `تعذر فتح المغلّف`,
  _U = `سباق الإمبراطور العظيم`,
  vU = `أصل الأبراج الصينية`,
  yU = `الجزء الأول من أربعة`,
  bU = `الجزء الثاني من أربعة`,
  xU = `الجزء الثالث من أربعة`,
  SU = `الجزء الرابع من أربعة`,
  CU = `استدعى الإمبراطور جايد جميع مخلوقات مملكته لخوض سباق نحو القصر السماوي، معلنًا أن أول اثني عشر مخلوقًا يصلون سيُمنحون شرف الظهور في تقويمه الجديد.
كان الجرذ الذكي أول من عبر النهر إلى العالم السماوي. وبما أنه لم يكن من محبي السباحة، ركب على ظهر الثور الوفي—ثم قفز بحماس إلى حديقة الإمبراطور قبل لحظات من وصولهما إلى الضفة.

عبر الثور الثابت النهر بسهولة. لم يكن مهتمًا بنتيجة السباق، بل شعر بالرضا لأنه ساهم في نجاح الجرذ.`,
  wU = `النمر الواثق بنفسه كان حذرًا في رحلته لدرجة أنه لم يتمكن من تجاوز الثور، مفضّلًا الوصول في المركز الثالث على أن لا يصل أبدًا.

الأرنب السريع قفز فوق جذع طافٍ في النهر لم يكن يتحرك بسرعة. لكن الحظ أنقذه حيث فشلت الخطة، إذ ساعدته ريح مواتية دفعت قاربه بسلام نحو الضفة.

أما التنين الطائر، فقد كشف له ارتفاعه قرية بحاجة إلى المساعدة، فتوقف دون تردد—بل أهدى الأرنب هبّة ريح عبر النهر. فبالنسبة إليه، كان الشرف أهم من النصر، ورضي تمامًا بالمركز الخامس.`,
  TU = `الثعبان الخفي لم يكن لديه اهتمام كبير ببذل مجهود لفترة طويلة، لذا التف حول حافر الحصان الأمامي دون أن يلحظه أحد. 

بينما كان الحصان يركض نحو خط النهاية، تحرر الثعبان، مما أرهب الخيل لفترة كافية ليحتل المركز السادس، بينما الحصان المذعور يركض خلفه.`,
  EU = `عمل الماعز والقرد والديك معًا، لكن تركوا الماعز يحتل المركز الثامن باعتباره العمود الفقري لرحلتهم. واحتل القرد المبتهج المركز التاسع، وتبعه الديك المتباهي في المركز العاشر، فخورًا بأن الترتيب كان عادلًا.

الكلب المرح كان مهتمًا في الغالب بالتجول، ليجد أن احتلال المركز الحادي عشر صفقة جيدة مقابل كل هذا المرح.

جاء الخنزير في المركز الأخير، الذي توقف لتناول وجبة خفيفة وأخذ غفوة - بحكمة كافية ليعرف أن كل حيوان سيقضي وقته لصالح الإمبراطور.`,
